import { existsSync } from 'node:fs';

import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

// Camera and diary-photo capture (#52). Chromium's fake media device stands in for the rear camera.
// Baselines are only ever generated by the e2e workflow's `update_snapshots` dispatch (e2e/README.md).
const PATH = `today?capture=camera`;
const SHEET = '[data-slot="camera-sheet"]';
const VIEWPORTS = [
  { name: '360', width: 360, height: 740 },
  { name: '768', width: 768, height: 1024 },
  { name: '1280', width: 1280, height: 800 },
] as const;

// `launchOptions` forces a new worker, so Playwright only allows it at the top level of a file.
test.use({
  permissions: ['camera'],
  launchOptions: {
    args: ['--use-fake-device-for-media-stream', '--use-fake-ui-for-media-stream'],
  },
});

test.describe('camera sheet', { tag: '@a11y' }, () => {
  test('captures pages into a strip, with the gallery picker always offered', async ({
    page,
    asUser,
  }) => {
    await asUser('owner', { path: PATH });
    await shellReady(page);
    const sheet = page.locator(SHEET);
    await expect(sheet.getByRole('button', { name: 'Take photo' })).toBeVisible();
    await expect(sheet.getByRole('button', { name: 'Choose photos' })).toBeVisible();
    await sheet.getByRole('button', { name: 'Take photo' }).click();
    await expect(sheet.getByRole('heading', { name: 'Adjust the page edges' })).toBeVisible();
    await sheet.getByRole('button', { name: 'Use this crop' }).click();
    await expect(sheet.getByRole('button', { name: 'Done (1)' })).toBeVisible();
    await expect(sheet.getByText('1 page captured')).toBeAttached();
    await sheet.getByRole('button', { name: 'Done (1)' }).click();
    await expect(sheet.getByRole('button', { name: 'Delete page 1' })).toBeVisible();
  });

  test('a page taken before a tab crash is offered back from the outbox', async ({
    page,
    asUser,
  }) => {
    await asUser('owner', { path: PATH });
    await shellReady(page);
    const sheet = page.locator(SHEET);
    await sheet.getByRole('button', { name: 'Take photo' }).click();
    await sheet.getByRole('button', { name: 'Use this crop' }).click();
    await expect(sheet.getByRole('button', { name: 'Done (1)' })).toBeVisible();
    // Reload without finishing: the held page is still in the encrypted outbox.
    await page.reload();
    await shellReady(page);
    await expect(page.locator(SHEET).getByText('Pick up where you left off')).toBeVisible();
    await page.locator(SHEET).getByRole('button', { name: 'Resume' }).click();
    await expect(page.locator(SHEET).getByRole('button', { name: 'Delete page 1' })).toBeVisible();
  });

  test('crop handles move with the arrow keys', async ({ page, asUser }) => {
    await asUser('owner', { path: PATH });
    await shellReady(page);
    const sheet = page.locator(SHEET);
    await sheet.getByRole('button', { name: 'Take photo' }).click();
    const handle = sheet.getByRole('slider', { name: /Top left corner/ });
    const before = await handle.getAttribute('aria-valuetext');
    await handle.focus();
    await page.keyboard.press('Shift+ArrowRight');
    await expect(handle).not.toHaveAttribute('aria-valuetext', before ?? '');
  });
});

test.describe('camera permission denied', () => {
  test.use({ permissions: [] });

  test('shows how to enable it and the gallery path', async ({ page, asUser }) => {
    await page.addInitScript(() => {
      Object.defineProperty(navigator.mediaDevices, 'getUserMedia', {
        value: () => Promise.reject(new DOMException('denied', 'NotAllowedError')),
      });
    });
    await asUser('owner', { path: PATH });
    await shellReady(page);
    const sheet = page.locator(SHEET);
    await expect(sheet.getByText('Camera access is off')).toBeVisible();
    await expect(sheet.getByRole('button', { name: 'Choose photos' })).toBeVisible();
  });
});

for (const theme of ['light', 'dark'] as const) {
  for (const viewport of VIEWPORTS) {
    test(
      `camera viewfinder ${theme} ${viewport.name}`,
      { tag: '@visual' },
      async ({ page, asUser }, testInfo) => {
        const name = `camera-viewfinder-${theme}-${viewport.name}.png`;
        const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
        test.skip(
          testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
          'no baseline yet: dispatch the e2e workflow with update_snapshots',
        );
        await page.setViewportSize({ width: viewport.width, height: viewport.height });
        await page.emulateMedia({ colorScheme: theme });
        await asUser('owner', { path: PATH });
        await shellReady(page);
        await expect(page.locator(SHEET)).toHaveScreenshot(name);
      },
    );
  }
}
